#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main() {
    double P, R, T;
    if (scanf("%lf", &P) != 1) return 0;
    if (scanf("%lf", &R) != 1) return 0;
    if (scanf("%lf", &T) != 1) return 0;

    double SI = (P * R * T) / 100.0;

    long long rounded = (long long)(SI + 0.5);
    double fraction = SI - rounded + 1.0;

    if (fabs(SI - rounded) < 1e-9) {
        printf("%lld\n", rounded);
    } else if (fabs(SI - floor(SI)) < 1e-9 && fabs(fraction - 1.0) < 1e-9) {
        printf("%lld\n", rounded);
    } else {
        printf("%lld\n", rounded);
    }

    return 0;
}
